  background: radial-gradient(circle at 34% 28%, #fff 0%, color-mix(in srgb, var(--yellow) 60%, #fff) 18%, var(--yellow) 55%, color-mix(in srgb, var(--yellow) 70%, #000) 100%);
  box-shadow: 0 7px 0 color-mix(in srgb, var(--yellow) 55%, #000), 0 0 0 5px var(--ink), 0 12px 10px rgba(0, 0, 0, 0.25);
