body[data-btn="arcade"] .btn-big::before { left: 18px; width: 44px; height: 44px; margin-top: -27px; }
body[data-btn="arcade"] .btn:hover::before { transform: translateY(-2px); box-shadow: 0 9px 0 color-mix(in srgb, var(--yellow) 55%, #000), 0 0 0 5px var(--ink), 0 14px 12px rgba(0, 0, 0, 0.25); }
body[data-btn="arcade"] .btn:active::before { transform: translateY(6px); box-shadow: 0 1px 0 color-mix(in srgb, var(--yellow) 55%, #000), 0 0 0 5px var(--ink), 0 3px 4px rgba(0, 0, 0, 0.25); }
body[data-btn="arcade"] .btn:hover { --drop: 4px; }
body[data-btn="arcade"] .btn:active { --drop: 2px; }
body[data-btn="arcade"] .btn-price { background: var(--ink); color: var(--paper); box-shadow: none; }

@font-face {
  font-family: "Archivo Black";
  src: url("../fonts/ArchivoBlack-Regular.ttf") format("truetype");
  font-display: swap;
}

:root {
  --ground: #f6f1ea;
  --paper: #fbf8f3;
  --ink: #15151a;
  --blue: #1f3fe0;
  --yellow: #f6c21a;
  --display: "Archivo Black", "Arial Black", sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --pad: clamp(16px, 2.2vw, 34px);
  --spring: cubic-bezier(0.3, 1.5, 0.5, 1);
  --out: cubic-bezier(0.2, 0.8, 0.2, 1);
}

* { box-sizing: border-box; margin: 0; }
html { background: var(--ground); }
/* the browser's own scrollbar in the page's two colours: a blue thumb on yellow while the page is light,
   a yellow thumb on blue once it is dark or blue (night, the film, its lens, the blue sky at the end), so it always stands out */
html { scrollbar-color: var(--blue) var(--yellow); }
html:has(body:is(.night, .proj, .sky-blue, .at-end)), html:has(#hud.is-on) { scrollbar-color: var(--yellow) var(--blue); }
body { scrollbar-color: auto; }      /* the colour is for the page's own scrollbar. It is handed down to every element unless it stops here, and then each change of chapter made the browser restyle and repaint the whole page */
@supports not (scrollbar-color: auto) {      /* older Safari */
  ::-webkit-scrollbar { width: 12px; } ::-webkit-scrollbar-track { background: var(--yellow); }
  ::-webkit-scrollbar-thumb { background: var(--blue); border-radius: 6px; border: 2px solid var(--yellow); }
}
body {
  color: var(--ink);
  font-family: var(--mono);
  font-size: 13px; line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}
::selection { background: var(--blue); color: #fff; }
a { color: inherit; }
ul { list-style: none; padding: 0; }

#world { position: fixed; inset: 0; width: 100vw; height: 100vh; height: 100dvh; display: block; touch-action: pan-y; }
body.grabbing, body.grabbing * { cursor: grabbing !important; }
body.can-grab { cursor: grab; }

