  return { root, update, hop, setWay, height: 1.15, lensWorld: (v) => eye.getWorldPosition(v) };
}

// The Colours stop: two sizes, four colours. One long stage with the three colours you are not wearing on the left and a
// Mosey XL on the right, a thin post between them with a brass mark at each height, and a printed plate under each.
// The card has a size switch. Pick XL and the robot you are walking grows to XL for as long as you are at this stop.
// js/main.js calls createSizes once, puts the group where the shop shelf used to be, and calls update() every frame.
// The switch's look is in css/style.css ("sizes"), its buttons are in index.html.
//   ?demo=1   clicks a colour, the XL and another colour for you, for recordings
export const XL = 1.58;      // the XL is the same robot, this much bigger: 22 cm to the base model's 14

export function createSizes(ctx) {
  const { THREE, RoundedBoxGeometry, scene, family, WAYS, createRobot, mats, at, DISPLAY, MONO, PAL } = ctx, [X, Z] = at;
  const group = new THREE.Group(); group.position.set(X, 0.65, Z);      // it pops up from 0.65 above the floor, the way the shelf did
  const F = -0.65, TOP = 0.6;                                            // the floor seen from inside the group, and how high the stage is
  const brass = new THREE.MeshStandardMaterial({ color: 0xb8924a, roughness: 0.32, metalness: 1 });
  const yellow = new THREE.MeshPhysicalMaterial({ color: PAL.accent, roughness: 0.38, clearcoat: 0.6, clearcoatRoughness: 0.25 });
  const add = (geo, mat, x, y, z) => { const m = new THREE.Mesh(geo, mat); m.castShadow = m.receiveShadow = true; m.position.set(x, y, z); group.add(m); return m; };
  add(new RoundedBoxGeometry(6.9, 0.12, 1.9, 3, 0.05), mats.ink, 0.1, F + 0.06, 0);                               // a dark foot
  add(new RoundedBoxGeometry(6.5, TOP - 0.17, 1.5, 4, 0.1), mats.blue, 0.1, F + 0.12 + (TOP - 0.17) / 2, 0);      // the stage
  add(new RoundedBoxGeometry(6.56, 0.05, 1.56, 2, 0.02), yellow, 0.1, F + TOP - 0.025, 0);                        // a yellow top edge
  add(new THREE.BoxGeometry(0.03, 1.95, 0.03), mats.ink, 1.28, F + TOP + 0.975, -0.45);                           // the post between the two sizes
  for (const h of [1.15, 1.15 * XL]) add(new THREE.BoxGeometry(0.5, 0.025, 0.03), brass, 1.28, F + TOP + h, -0.45);      // and a mark at the top of each head
  // a printed plate: a name, and a line under it
  const plate = (name, sub, x) => {
    const cv = document.createElement('canvas'); cv.width = 512; cv.height = 90; const k = cv.getContext('2d'), tex = new THREE.CanvasTexture(cv); tex.colorSpace = THREE.SRGBColorSpace; tex.anisotropy = 8;
    const draw = () => { k.fillStyle = PAL.paper; k.fillRect(0, 0, 512, 90); k.strokeStyle = PAL.ink; k.lineWidth = 10; k.strokeRect(5, 5, 502, 80); k.fillStyle = PAL.ink; k.textAlign = 'center'; k.textBaseline = 'middle';
      k.font = `36px ${DISPLAY}`; k.fillText(name.toUpperCase(), 256, 33); k.font = `600 18px ${MONO}`; k.fillText(sub.toUpperCase(), 256, 67); tex.needsUpdate = true; };
    draw(); document.fonts?.ready.then(draw);      // once more when the page's own typeface has arrived
    const m = new THREE.Mesh(new THREE.PlaneGeometry(1.7, 0.3), new THREE.MeshBasicMaterial({ map: tex, toneMapped: false })); m.position.set(x, F + 0.33, 0.76); group.add(m);
  };
  plate('Mosey', '14 cm · $149', -1.2); plate('Mosey XL', '22 cm · $249', 2.35);
  [-2.35, -1.2, -0.05].forEach((x, i) => { family[i].r.root.position.set(X + x, TOP, Z + 0.05); family[i].r.root.rotation.y = -0.1 + i * 0.1; });
  const big = createRobot(); big.root.position.set(X + 2.35, TOP, Z); big.root.rotation.y = -0.18; big.root.scale.setScalar(XL); big.root.visible = false; scene.add(big.root);

  // the card's size switch
  const buttons = [...document.querySelectorAll('.size-sw button')], line = document.getElementById('sizeline');
  const LINES = { base: '14 cm. Walks 6 hours. Puts 40 inches on a wall.', xl: '22 cm. Walks 12 hours. Puts 80 inches on a wall, and carries your tea.' };
  let size = 'base', grow = 1, lastWay = null;
  function setSize(s) {
    size = s; line.textContent = LINES[s];
    buttons.forEach((b) => { const on = b.dataset.size === s; b.classList.toggle('is-on', on); b.setAttribute('aria-pressed', on); });
    ctx.robot.hop(s === 'xl' ? 5 : 3); big.hop(s === 'xl' ? 5 : 2.5);
  }
  buttons.forEach((b) => b.addEventListener('click', () => setSize(b.dataset.size)));

  // ?demo=1: once the card is up, a colour, then the XL, then another colour
  const DEMO = new URLSearchParams(location.search).has('demo'), card = document.querySelector('.size-sw').closest('.copy'), plan = [[1.4, 'mint'], [3.2, 'xl'], [5.4, 'sunny']];
  let t0 = 0, n = 0;
  function demo() {
    if (!card.classList.contains('is-on')) { t0 = 0; n = 0; return; }
    t0 ||= performance.now(); const t = (performance.now() - t0) / 1000;
    while (n < plan.length && t > plan[n][0]) { const k = plan[n++][1]; if (k === 'xl') setSize('xl'); else document.querySelector(`.swatches button[data-way="${k}"]`)?.click(); }
  }

  return { group, update({ way, dt, T, d, M }) {
    if (way !== lastWay) { lastWay = way; big.setWay(way); }                               // the XL wears the colour you picked
    const here = d > M.gate - 1 && d < M.price + 0.6;                                      // you are only XL while you are at this stop
    grow += ((here && size === 'xl' ? XL : 1) - grow) * (1 - Math.exp(-7 * dt));
    ctx.robot.root.scale.setScalar(Math.abs(grow - 1) > 0.002 ? grow : 1);
    const lead = family[0].r.root; big.root.visible = lead.visible;                         // it comes and goes with the others
    if (big.root.visible) { big.root.scale.setScalar(XL * lead.scale.x); big.update({ dist: 0, speed: 0, air: -1, falling: false, idleFor: 0, look: { yaw: 0.25, pitch: 0 }, act: size === 'xl' ? { name: 'wave', t: 0 } : null, dt, time: T + 3.1 }); }
    if (DEMO) demo();
  } };
}

// The sound of the walk. Nothing here is a recording: every sound is made in the browser as you scroll, so it follows the scroll.
// The page is a music box and the scroll is its crank. Stop scrolling and it goes quiet.
//   the steps   one soft tap each time a foot comes down. They come from the robot's own walk cycle, so they match what you see
//   the tune    a slow line of plucked notes, one every little stretch of the walk. Scroll back and it plays backwards
//   the bed     four held notes under everything. They change with the chapter, swell while you scroll and sink when you stop
//   the air     a breath of noise that follows how fast you scroll, and turns into wind on the jumps and the last fall
//   moments     a card switching on, a thing it locks on to through its lens, a notification on your phone, the buttons
// It starts when you press PRESS, or with the switch in the top bar, and that switch turns all of the page's sound off again.
// It all goes through the page's one volume (sfx in js/main.js). The switch's look is in css/style.css ("the sound switch").
//   ?sound=1   starts it without a press, for recordings (a normal browser still wants a click first)
const Q = new URLSearchParams(location.search);
const clamp = (v, a, b) => Math.max(a, Math.min(b, v)), sat = (v) => clamp(v, 0, 1);
const hz = (semi) => 293.66 * 2 ** (semi / 12);      // a note, counted in semitones up from the D above middle C

// How loud each part is. 1 would be as loud as the page can go. The recorded sounds (the press, the landings) sit a little above these
const VOL = { bed: 0.03, step: 0.05, tune: 0.075, chime: 0.06, air: 0.02, wind: 0.07, ui: 0.05, ping: 0.1 };

// The chapters. chord: the four notes held under it. lp: how bright the bed is (Hz). tune: how loud the plucked line is here,
// oct: how high it plays, ring: how long each note rings (s), dull: muffled steps, because you are inside its head
const SCENES = {
  day:   { chord: [-12, -5, 4, 2], lp: 820, tune: 1, oct: 0, ring: 0.9 },                       // D, A, F sharp, E: home
  night: { chord: [-15, -8, 0, 7], lp: 560, tune: 0.8, oct: 0, ring: 1.5 },                     // B, F sharp, D, A: the lights are out
  lens:  { chord: [-12, -7, -3, 2], lp: 400, tune: 0.55, oct: 12, ring: 0.3, dull: true },      // D, G, B, E: low and close, with short high blips
  proj:  { chord: [-12, -7, -3, 4], lp: 430, tune: 0, oct: 0, ring: 1 },                        // nearly the same, held still: the film has the floor
  show:  { chord: [-17, -10, 1, -3], lp: 980, tune: 1, oct: 0, ring: 1 },                       // A, E, C sharp, B: brighter, and it wants to go home
  sky:   { chord: [-12, -5, 4, 7], lp: 1500, tune: 1, oct: 12, ring: 1.3 },                     // D again, an octave of air above it
};
// The tune, in semitones from D. Five notes only (D, E, F sharp, A, B), so no two of them can clash. null is a rest
const TUNE = [0, null, 4, 7, null, 4, 9, null, 7, null, 4, 2, null, -5, 0, null, 7, null, 9, 12, null, 9, 7, null, 4, null, 7, 2, null, 0, -3, null];
const GAP = 1.5;      // how far you walk between two notes of it

// the switch in the top bar: four bars that move while the sound is on
const sw = Object.assign(document.createElement('button'), { className: 'snd', id: 'snd', type: 'button', innerHTML: '<i></i><i></i><i></i><i></i><span class="sr">Sound</span>' });
sw.setAttribute('aria-pressed', 'false'); sw.title = 'Sound';
document.querySelector('.bar .btn').before(sw);

let on = false, G = null;      // G: everything that makes sound, built the first time it is turned on
function setOn(v) {
  const m = window.__mosey; if (!m) return;
  on = v; m.sfx.set(v); sw.setAttribute('aria-pressed', v); document.body.classList.toggle('snd-on', v);
  if (v && !G && m.sfx.ctx) G = build(m.sfx.ctx, m.sfx.out);
  if (G) G.bus.gain.setTargetAtTime(v ? 1 : 0, G.ctx.currentTime, v ? 0.5 : 0.05);
}
sw.addEventListener('click', () => { setOn(!on); if (on) G?.tick(); });
// PRESS turns it on. Caught on the way down to the button, so the volume is open before the button's own click sound plays
document.addEventListener('click', (e) => { if (!on && e.target.closest?.('#unbox')) setOn(true); }, true);
document.addEventListener('visibilitychange', () => { const c = window.__mosey?.sfx.ctx; if (!c) return; if (document.hidden) c.suspend(); else if (on) c.resume(); });
if (Q.has('sound')) { const t = setInterval(() => { if (window.__mosey?.boot.firstFrame) { clearInterval(t); setOn(true); } }, 100); }

// The room and the noise are two seconds of random numbers each. Making them takes a moment, so it is done ahead, in the quiet
// seconds while the intro plays. Done inside the click on PRESS, it made that click the longest frame of the page on a slow phone.
const PRE = { rate: 48000, room: null, hiss: null };
const roomSide = (rate) => { const n = Math.floor(rate * 2.2), a = new Float32Array(n); let lp = 0; for (let i = 0; i < n; i++) { lp += (Math.random() * 2 - 1 - lp) * 0.3; a[i] = lp * (1 - i / n) ** 3.4; } return a; };
const noise = (rate) => { const a = new Float32Array(rate * 2); for (let i = 0; i < a.length; i++) a[i] = Math.random() * 2 - 1; return a; };
{ const idle = (f) => (window.requestIdleCallback ? requestIdleCallback(f, { timeout: 3000 }) : setTimeout(f, 60));      // three small jobs, each when the page has a free moment
  setTimeout(() => idle(() => { const l = roomSide(PRE.rate); idle(() => { PRE.room = [l, roomSide(PRE.rate)]; idle(() => { PRE.hiss = noise(PRE.rate); }); }); }), 1200); }

